namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Measurement;

internal sealed class FourQubitParentConstructionDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/Quantum/Measurement/FourQubitParentConstruction.";
    private static readonly LibraryNoteRef Source = LibraryNoteRef.Create("D5/L/QuantumBounds/bluhm2025inclusion");
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "FourQubitParentConstruction: exact analytic statements for four-qubit white-noise compatibility.",
        H("FourQubitParentConstruction"),
        Blocks(
            Node("Compatible4", "Compatible4", "Definition 2.13 (p. 12): “Let g ∈ ℕ, d ∈ ℕ, and kₓ ∈ ℕ for all x ∈ [g]. Let (Eᵢ∣ₓ)ᵢ∈[kₓ], x ∈ [g] be a collection of g d-dimensional POVMs. These measurements are compatible if there exists another d-dimensional POVM (Jᵢ₁,…,ᵢg)ᵢ₁∈[k₁],…,ᵢg∈[kg] such that” the marginal equality holds. Here g = 4, d = 2 and each outcome set is Bool. The sixteen functions Fin 4 → Bool index the joint outcomes; true denotes the positive sign.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source), All("E", Measurements(), Equal(Call("Compatible4", X("E")), And(All("i", Fin(4), Call("IsPOVM", Apply(X("E"), X("i")))), Ex("J", Parents(), And(Call("IsPOVM", X("J")), All("i", Fin(4), All("b", BoolType(), Equal(Apply(X("E"), X("i"), X("b")), Marginal(X("J"), X("i"), X("b"))))))))))),
            Node("noisy", "noisy", "Definition 2.15 (p. 13): “Let k ∈ ℕ and let (Eᵢ)ᵢ∈[k] be a POVM. Let s ∈ [0, 1] be a noise parameter. Then, we define the POVM (Eᵢ(s))ᵢ∈[k] with” Eᵢ(s) := sEᵢ + (1 − s)I/k “as the noisy version of (Eᵢ)ᵢ∈[k].” Here k = 2 and real scalars act on complex matrices.", DescribeRole.Definition, AssessedProvenance.FromLiterature(Source), All("s", Reals(), All("E", Measurements(), All("i", Fin(4), All("b", BoolType(), Equal(Call("noisy", X("s"), X("E"), X("i"), X("b")), Add(Smul(X("s"), Apply(X("E"), X("i"), X("b"))), Smul(Subtract(Num(1), X("s")), Smul(Typed(Fraction(Num(1),Num(2)), Complexes()), Identity()))))))))),
            Node("endpoint", "endpoint", "The sharp retained-signal parameter is 2/√13.", DescribeRole.Definition, AssessedProvenance.FromRepo(), Equal(Typed(X("endpoint"), Reals()), Fraction(Num(2), Root(Num(13))))),
            Node("B_formula", "B_formula", "The Pauli expansion gives these four complex matrix entries.",
                DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("a", Vectors(),
                    Equal(Call("B", X("a")), Mat(Typed(Apply(X("a"), Num(2)), Complexes()),
                        Subtract(Typed(Apply(X("a"), Num(0)), Complexes()),
                            Multiply(Qualified("Complex", "I"), Typed(Apply(X("a"), Num(1)), Complexes()))),
                        Add(Typed(Apply(X("a"), Num(0)), Complexes()),
                            Multiply(Qualified("Complex", "I"), Typed(Apply(X("a"), Num(1)), Complexes()))),
                        Negate(Typed(Apply(X("a"), Num(2)), Complexes())))))),
            Node("B_zero", "B_zero", "The zero Bloch vector gives the zero matrix.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), Equal(Call("B", Typed(Num(0), Vectors())), Typed(Num(0), Matrices()))),
            Node("B_real_smul", "B_real_smul", "The Bloch matrix is homogeneous for the real scalar action.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("c", Reals(), All("a", Vectors(), Equal(Call("B", Smul(X("c"),X("a"))), Smul(X("c"), Call("B",X("a"))))))),
            Node("B_neg", "B_neg", "Negating the vector negates its Bloch matrix.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("a", Vectors(), Equal(Call("B", Negate(X("a"))), Negate(Call("B",X("a")))))),
            Node("B_sum", "B_sum", "The Bloch expansion commutes with finite sums.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("U", X("Type"), All("s", Call("Finset", X("U")), All("a", Arrow(X("U"), Vectors()), Equal(Call("B", SumIn("i",X("s"), Apply(X("a"),X("i")))), SumIn("i",X("s"), Call("B",Apply(X("a"),X("i"))))))))),
            Node("norm_sq_coords", "norm_sq_coords", "The squared Euclidean norm is the sum of the three coordinate squares.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("a", Vectors(), Equal(Pow(Norm(X("a")),2), Add(Add(Pow(Apply(X("a"),Num(0)),2), Pow(Apply(X("a"),Num(1)),2)), Pow(Apply(X("a"),Num(2)),2))))),
            Node("trace_B_mul", "trace_B_mul", "The trace pairing of Bloch matrices is twice the real inner product.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("a", Vectors(), All("b", Vectors(), Equal(Apply(Qualified("Matrix","trace"),Multiply(Call("B",X("a")),Call("B",X("b")))), Typed(Multiply(Num(2), Call("inner",Reals(),X("a"),X("b"))), Complexes()))))),
            Node("scalarB_sum", "scalarB_sum", "Scalar and Bloch coordinates commute with finite sums.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("U", X("Type"), All("s", Call("Finset", X("U")), All("t", Arrow(X("U"), Reals()), All("a", Arrow(X("U"), Vectors()), Equal(Call("scalarB", SumIn("j", X("s"), Apply(X("t"), X("j"))), SumIn("j", X("s"), Apply(X("a"), X("j")))), SumIn("j", X("s"), Call("scalarB", Apply(X("t"), X("j")), Apply(X("a"), X("j")))))))))),
            Node("scalarB_hermitian", "scalarB_hermitian", "Real scalar and Bloch coordinates define a Hermitian matrix.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("t",Reals(), All("a",Vectors(), Apply(Qualified("Matrix","IsHermitian"),Call("scalarB",X("t"),X("a")))))),
            Node("hermitian_decomposition", "hermitian_decomposition", "Every Hermitian two by two matrix is reconstructed from its real trace and Bloch coordinates.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("A",Matrices(), Implication(Apply(Qualified("Matrix","IsHermitian"),X("A")), Equal(X("A"),Call("scalarB",Fraction(Apply(Qualified("Complex","re"),Apply(Qualified("Matrix","trace"),X("A"))),Num(2)),Smul(Typed(Fraction(Num(1),Num(2)),Reals()),Call("bloch",X("A")))))))),
            Node("half_scalarB_double", "half_scalarB_double", "Doubling both coordinates and multiplying the matrix by one half gives the original matrix.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("t",Reals(), All("a",Vectors(), Equal(Smul(Typed(Fraction(Num(1),Num(2)),Complexes()),Call("scalarB",Multiply(Num(2),X("t")),Smul(Typed(Num(2),Reals()),X("a")))),Call("scalarB",X("t"),X("a")))))),
            Node("half_scalarB_complement", "half_scalarB_complement", "The complementary effect negates the Bloch vector and replaces the scalar by two minus that scalar.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("t",Reals(), All("a",Vectors(), Equal(Smul(Typed(Fraction(Num(1),Num(2)),Complexes()),Call("scalarB",Subtract(Num(2),X("t")),Negate(X("a")))),Subtract(Identity(),Smul(Typed(Fraction(Num(1),Num(2)),Complexes()),Call("scalarB",X("t"),X("a")))))))),
            Node("scalarB_posSemidef_iff", "scalarB_posSemidef_iff", "The determinant and diagonal entries give the necessary bound. At the boundary, the square identity expresses the matrix as a positive multiple of its conjugate-transpose square; adding a nonnegative scalar identity yields sufficiency.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("t",Reals(), All("a",Vectors(), Equivalence(Apply(Qualified("Matrix","PosSemidef"),Call("scalarB",X("t"),X("a"))), LE(Norm(X("a")),X("t")))))),
            Node("half_scalarB_posSemidef_iff", "half_scalarB_posSemidef_iff", "Multiplication by the positive scalar 1/2 preserves the positivity criterion.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("t",Reals(), All("a",Vectors(), Equivalence(Apply(Qualified("Matrix","PosSemidef"),Smul(Typed(Fraction(Num(1),Num(2)),Complexes()),Call("scalarB",X("t"),X("a")))), LE(Norm(X("a")),X("t")))))),
            Node("endpoint_mem_Icc", "endpoint_mem_Icc", "The sharp endpoint lies in the permitted retention interval.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), Member(X("endpoint"),Interval(Num(0),Num(1)))),
            Node("compatible_of_parent", "compatible_of_parent", "A POVM with these marginal sums establishes compatibility.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("E",Measurements(),All("J",Parents(),Implication(Call("IsPOVM",X("J")),Implication(All("i",Fin(4),All("b",BoolType(),Equal(Apply(X("E"),X("i"),X("b")),Marginal(X("J"),X("i"),X("b"))))),Call("Compatible4",X("E"))))))),
            Node("all_povms_compatible", "all_povms_compatible", "A compact convex sign decomposition follows from the four-vector inequality and the projection theorem. Antipodal effects give a joint parent for unbiased measurements. Each biased effect is obtained by a stochastic channel from a unit-vector effect and the two deterministic effects; applying these channels to the parent preserves every marginal.", DescribeRole.Theorem, AssessedProvenance.FromRepo(), All("E",Measurements(),Implication(All("i",Fin(4),Call("IsPOVM",Apply(X("E"),X("i")))),Call("Compatible4",Call("noisy",X("endpoint"),X("E")))))),
            Paragraph(Text("Application correspondence: a total sign selection on the full self-adjoint qubit carrier. Here E is selfAdjoint (Matrix (Fin 2) (Fin 2) ℂ), u is the identity, the cone is the usual positive-semidefinite cone, the norm is the matrix operator norm, and a ∘ b = (ab + ba)/2. The original inputs are all of E. The matrices X₁, X₂, X₃ are respectively [[0,1],[1,0]], [[0,−i],[i,0]], [[1,0],[0,−1]]. They are the existing pauliMatrix X, Y, Z; scalarB supplies αu + x·σ. The theorem hermitian_decomposition gives α = Re(trace a)/2 and x = bloch(a)/2 for every original a. Uniqueness is exactly BiasedTrineJointMeasurabilityThreshold.scalarB_injective. The existing scalarB_hermitian and scalarB_posSemidef_iff identify the carrier and its full cone: αu + x·σ is positive precisely when ‖x‖ ≤ α. This correspondence includes every scalar and every degenerate Bloch vector; it is not a restriction to pure states or normalized matrices.")),
            Paragraph(Text("For a = αu + x·σ and b = γu + y·σ, put K(a,b) = (ab − ba)/(2i) = (x × y)·σ and L(a,b) = α² + γ² − ‖x‖² − ‖y‖². Let ε(a,b) be +1 when L(a,b) ≤ 0, including the equality boundary, and −1 otherwise. The one total response is Dₛ(a,b) = ε(a,b)K(a,b). Equivalently, K(a,b) is imaginaryPart(ab), while a ∘ b is realPart(ab), so realPart_add_I_smul_imaginaryPart identifies ab = a ∘ b + iK(a,b). The scalarB entries reduce this equality to the usual Pauli multiplication; Xⱼ² = u, X₁X₂ = iX₃ and cyclic permutations, with reversed products negated. The construction adds no continuity, additivity, homogeneity or complex-input extension of Dₛ.")),
            Paragraph(Text("The sign rule preserves exchange and separate negation because L(b,a) = L(a,b), L(−a,b) = L(a,b) = L(a,−b); K changes sign in each of these operations. Thus Dₛ(b,a) = −Dₛ(a,b), Dₛ(−a,b) = −Dₛ(a,b) and Dₛ(a,−b) = −Dₛ(a,b). For every real angle θ, mix the ordered input-label pair itself: aθ = cos(θ)a − sin(θ)b and bθ = sin(θ)a + cos(θ)b. Both the scalar pair (α,γ) and each pair of spatial coordinates undergo the same rotation. The identity cos²(θ) + sin²(θ) = 1 gives L(aθ,bθ) = L(a,b), and bilinearity and alternation of the commutator give K(aθ,bθ) = K(a,b). Hence Dₛ(aθ,bθ) = Dₛ(a,b). This is SO(2) rotation of the two ordered labels, not merely rotation of spatial axes.")),
            Paragraph(Text("All zero rows have their original real quantifiers. For all μ and b, Dₛ(μu,b) = 0. For all s,t,r,q and a, Dₛ(su + ra, tu + qa) = 0, since the vector parts rx and qx are parallel. For all λ and a, Dₛ(a,λa²) = 0: the vector part of a² is 2αx. Equivalently these are commuting pairs, so imaginaryPart of their product vanishes before the sign is selected. Zero, repeated, proportional and scalar inputs are all included, without a nonzero or invertibility premise.")),
            Paragraph(Text("The readings range over every positive real-linear functional β : E → ℝ, with positivity meaning β(h) ≥ 0 for every positive-semidefinite h. There is no normalization premise on β(u). The vector readings βᵥ(h) = Re(v*hv) are positive for every complex vector v; Matrix.PosSemidef.of_dotProduct_mulVec_nonneg and IsHermitian.im_star_dotProduct_mulVec_self show that all positive real readings detect exactly the given cone, and applying the cone test to h and −h shows that these readings separate the full carrier. Define its complex-linear extension on the entire ambient matrix algebra by β̃(T) = β(realPart T) + iβ(imaginaryPart T). The pinned realPart_smul and imaginaryPart_smul identities supply complex linearity, and selfAdjoint.realPart_coe and selfAdjoint.imaginaryPart_coe supply agreement on every original h, not only on effects. If T is positive, its imaginary part is zero and its real part is T, so β̃ is positive. The same extension construction is an existing closed result, ProbabilisticTheory.complexExtension, in leanprover-community/physlib at revision 4e2182f2b6f0a54207a2fa62002c264217f875d6; that repository is not an admitted dependency here. EffectProbabilityExtension.effect_linear_extension alone supplies agreement on effects and must not be silently substituted for the full-carrier agreement just described.")),
            Paragraph(Text("For any finite original self-adjoint list Aⱼ, set Mⱼₖ = β̃(AⱼAₖ). This is exactly Matrix.gram ℂ (fun j => β̃.toPreGNS Aⱼ), because Aⱼ* = Aⱼ and PositiveLinearMap.preGNS_inner_def identifies each entry. Matrix.posSemidef_gram supplies positivity for every mass, including β = 0. Its transpose is positive by Matrix.PosSemidef.transpose; Hermitian symmetry identifies that transpose with entrywise complex conjugation. For the list (μu,a,b), every unit-row commutator and every diagonal commutator vanishes. Its response table Gⱼₖ = β(Aⱼ ∘ Aₖ) − iβ(Dₛ(Aⱼ,Aₖ)) is M when ε(a,b) = −1, and Mᵀ when ε(a,b) = +1. The reversed entry uses the same sign because L is exchange invariant. Thus the whole table, for all real μ and all original a,b, is positive semidefinite. Repetitions, zero labels, permutations and principal sublists are covered by Matrix.PosSemidef.submatrix; the argument does not select independent labels or normalize a reading.")),
            Paragraph(Text("Taking the a,b principal subtable gives all-mass P2. Its determinant is β(a²)β(b²) − β(a ∘ b)² − β(Dₛ(a,b))², so determinant nonnegativity is the exact bound |β(Dₛ(a,b))|² ≤ β(a²)β(b²) − β(a ∘ b)². When m = β(u) = 0, the order-unit bounds −‖h‖u ≤ h ≤ ‖h‖u give |β(h)| ≤ ‖h‖m = 0 for every original h, so the entire table is zero. Every positive mass, including subnormalized and unequal masses assigned to different readings, remains in the same argument. No identification of all positive mathematical functionals with actual preparations is used.")),
            Paragraph(Text("Actual unit translation fails. The exact coordinates give L(X₁,X₂) = −2, K(X₁,X₂) = X₃ and Dₛ(X₁,X₂) = X₃, whereas L(2u + X₁,X₂) = 2, K(2u + X₁,X₂) = X₃ and Dₛ(2u + X₁,X₂) = −X₃. Both are calls to the same total map on original matrices. The unit row being zero therefore does not force cross-axis translation invariance.")),
            Paragraph(Text("Actual vector-action fibers also fail. Use the standard identity representation of the full matrix algebra on ℂ², with its usual Hermitian inner product, ξ = (1,0)ᵀ and βξ(h) = ξ* h ξ. This representation acts by Matrix.toLinAlgEquiv′; it is irreducible since arbitrary matrices send any nonzero vector onto all of ℂ². The vector has norm one and βξ is a positive real-linear reading of mass one. PureStateHandshake.rankOneDensity ξ is its normalized positive rank-one density; pure_state_handshake supplies its idempotency and the exact identity βξ(h) = Re(trace(h rankOneDensity ξ)). Put p₋ = (u − X₃)/2, A = u + X₁, A′ = A + 2p₋ = 2u + X₁ − X₃, and B = B′ = X₂. The actual equalities are 2p₋ξ = 0, Aξ = A′ξ = (1,1)ᵀ, and Bξ = B′ξ = (0,i)ᵀ. Yet L(A,B) = −1 and K(A,B) = X₃, while L(A′,B′) = 1 and K(A′,B′) = X₁ + X₃. Consequently βξ(Dₛ(A,B)) = 1 and βξ(Dₛ(A′,B′)) = −1. Equality of input vector actions, rather than merely equality of expectations, is the fiber being tested.")),
            Paragraph(Text("The full original PB fails at the original triple (a,b,c) = (X₁,2u + X₂,0). Write v = Dₛ(a,b) − a ∘ c and w = a ∘ b + Dₛ(a,c), exactly as in the original nested calls. The inner values are Dₛ(a,b) = −X₃ and Dₛ(a,c) = 0, hence v = −X₃ and w = 2X₁. Thus r₊ = b + v = 2u + X₂ − X₃, s₊ = c + w = 2X₁, r₋ = b − v = 2u + X₂ + X₃, and s₋ = c − w = −2X₁. Both outer pairs have L = −2. Their actual outputs are Dₛ(r₊,s₊) = −2X₃ − 2X₂ and Dₛ(r₋,s₋) = 2X₃ − 2X₂. Their difference is −4X₃, whereas the PB finite-difference right-hand side −2b ∘ v − 2c ∘ w is 4X₃.")),
            Paragraph(Text("The original square-reading PB gives the same explicit failure without replacing its nested calls by a new condition. Here r±² = 6u + 4X₂ ∓ 4X₃ and s±² = 4u. Therefore r₊² + s₊² + 2Dₛ(r₊,s₊) = 10u − 8X₃ and r₋² + s₋² + 2Dₛ(r₋,s₋) = 10u + 8X₃. The same βξ reads these two original square expressions as 2 and 18, respectively. This response is consequently excluded by full PB; it supplies a separation of the stated weaker conditions and does not supply a countermodel to P2 together with full PB.")),
            Paragraph(Text("The four-label diagnostic uses the existing zero-direction mechanism, supplied generically by Matrix.PosSemidef.dotProduct_mulVec_zero_iff. For a single response D with P2, antisymmetry and full zero unit rows, let G be the actual table on (u,a,a + λu,b), h = D(a + λu,b) − D(a,b), η = β(h), q = β(b²), and z₀ = (−λ,−1,1,0)ᵀ. The original real relation −λu − a + (a + λu) = 0, Jordan bilinearity and the zero rows give z₀*Gz₀ = 0 and z₀*Ge₄ = −iη. Expanding this very table gives (z₀ − it e₄)*G(z₀ − it e₄) = t²q − 2tη for every real t. If q = 0, P2 on both original pairs forces η = 0. If η ≠ 0 then q > 0, and t = η/q gives −η²/q < 0. Nonnegativity of all these specified tilts therefore forces η = 0; separating positive readings would then force h = 0. No common-table positivity or PB-to-tilt implication is supplied by this application, and no additional generic zero-direction theorem is needed.")),
            Paragraph(Text("For the same Dₛ, take the four original labels (u,X₁,2u + X₁,X₂), λ = 2 and the same βξ. Then η = −2 and q = 1. The coefficient vector z₀ − it e₄ at t = −2 is exactly (−2,−1,1,2i)ᵀ, and its quadratic reading is exactly −4. Thus this actual four-label table is not positive, although every real-unit-anchored three-label table is positive. The complex numbers here are table coefficients only: every input to Dₛ remains an original self-adjoint matrix.")),
            Paragraph(Text("The real geometry of this translation diagnostic is spanℝ{u,a,b}. Under the stated affine zero rows, dependence of u and a makes both translated first inputs scalar and gives zero defect; if u,a are independent and the span has dimension at most two then b = su + ra and the same affine zero rows again give zero defect. Three independent real directions are therefore required for this particular nonzero translation defect. The four labels encode a redundant real relation within their at most three-dimensional span. This does not classify the minimum number of labels for arbitrary test classes. Such a span need not be closed under Jordan multiplication or D, need not have finite spectral or corner structure, and is not physical three-space. In the example X₃ lies outside spanℝ{u,X₁,X₂}.")),
            Paragraph(Text("The application reuses Pauli algebra, self-adjoint decomposition, positive-functional Gram positivity and the zero-direction mechanism. It adds no independent axiom and asserts no literature priority. Raw/PB-dependent UnitBridgeRawGeometry conclusions cannot supply a law for this response, and PauliFixedProductFamily has a different carrier. The weighted conclusions using full PB retain their own assumptions and do not apply merely because this example has the weaker symmetries and unit triples. The general JB and possibly incomplete original-domain translation and additivity bridges, the full-C* action-fiber and bilinearity equivalence and the conditional finite-table and associative-product consumers keep their original premises. There is no general JB-to-C* completion, physical realization, reduction of independent axioms, or completion of the quantum-origin objective here.")),
            Paragraph(Text("All original source obligations remain: Ω/native and full K/J/q words; parent positions and ready types; the original center and unequal-dimensional blocks; all zero, unequal and subnormalized masses; actual preparation and complete effect menus; common records and genuine grouping and forgetting; full instruments, environments and every output; actual correlated joints and recursively common-source references; every legal sequential, adaptive and parallel history with every still legal future; stopping, refusal and destruction; equal-number sides and genuine inverse returns. A mathematical matrix, positive reading or vector action supplies none of those physical sources. Born ratios require the original actual complete menu and strictly positive mass; zero mass is not normalized. Infinite CountRead, nondiscrete records, countable additivity, normality and preduals, physical clocks, energy and a common action scale ℏ each retain their source conditions."))), []));
    private static DocumentBlock Node(string name, string title, string prose, DescribeRole role, AssessedProvenance provenance, Formula formula) => Describe.Lean(
        DescribeId.Create(name.Replace("_", "-").ToLowerInvariant()), DeclarationHandle.Create(Prefix + name), H(title),
        StatementSource.FromAuthor(Disp(formula)), provenance, Blocks(Paragraph(Text(prose))), role);

    private static Formula X(string name) => F.Id(name);
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
    private static Formula Typed(Formula value, Formula type) => Parenthesized(Seq(value, Colon, Sp, type));
    private static Formula Reals() => Seq(Mathbb, Grp(X("R")));
    private static Formula Complexes() => Seq(Mathbb, Grp(X("C")));
    private static Formula Fin(byte n) => Call("Fin", D(n));
    private static Formula BoolType() => X("Bool");
    private static Formula Vectors() => Call("EuclideanSpace", Reals(), Fin(3));
    private static Formula Matrices() => Call("Matrix", Fin(2), Fin(2), Complexes());
    private static Formula Signs() => Arrow(Fin(4), BoolType());
    private static Formula Measurements() => Arrow(Fin(4), Arrow(BoolType(), Matrices()));
    private static Formula Parents() => Arrow(Signs(), Matrices());
    private static Formula Arrow(Formula a, Formula b) => new Formula.TypeArrow(a, b);
    private static Formula Apply(Formula fn, params Formula[] args) => new Formula.Apply(fn, [.. args]);
    private static Formula Qualified(string owner, string name) => Seq(Operatorname, Grp(X(owner), Dot, X(name)));
    private static Formula All(string v, Formula domain, Formula body) => new Formula.Bind(FormulaQuantifier.ForAll, FormulaIdentifier.Create(v), domain, body);
    private static Formula Ex(string v, Formula domain, Formula body) => new Formula.Bind(FormulaQuantifier.Exists, FormulaIdentifier.Create(v), domain, body);
    private static Formula Norm(Formula a) => new Formula.Norm(a);
    private static Formula Negate(Formula a) => new Formula.Negate(a);
    private static Formula Pow(Formula a, long n) => new Formula.Power(a, Num(n));
    private static Formula Fraction(Formula a, Formula b) => new Formula.Fraction(a,b);
    private static Formula Root(Formula a) => Seq(Sqrt, Grp(a));
    private static Formula Smul(Formula a, Formula b) => Seq(Parenthesized(a), Sp, Cdot, Sp, Parenthesized(b));
    private static Formula LE(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.LessThanOrEqual, b);
    private static Formula Member(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.MemberOf, b);
    private static Formula And(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.And, b);
    private static Formula Implication(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Implies, b);
    private static Formula Equivalence(Formula a, Formula b) => new Formula.Logic(a, FormulaLogicOperator.Iff, b);
    private static Formula Identity() => Typed(Num(1), Matrices());
    private static Formula Mat(Formula a, Formula b, Formula c, Formula d) => Seq(Begin, Grp(X("pmatrix")), a, Amp, b, RowBreak, c, Amp, d, End, Grp(X("pmatrix")));
    private static Formula Interval(Formula a, Formula b) => Apply(Qualified("Set","Icc"),a,b);
    private static Formula SumIn(string v, Formula s, Formula b) => Seq(new Formula.Subscript(Sum, Member(X(v), s)), Sp, b);
    private static Formula Marginal(Formula J, Formula i, Formula b) => Seq(new Formula.Subscript(Sum, Seq(Typed(X("e"),Signs()), Comma, Sp, Equal(Apply(X("e"),i), b))), Sp, Apply(J,X("e")));
}
